        20 => ['имя' => 'тёплый камень', 'тон' => [150, 140, 130], 'а1' => .10, 'а2' => .17, 'кант' => 'solid 1px', 'акцент' => '#f5c84c', 'радиус' => .6, 'пилюля' => false, 'тень' => 'box-shadow:0 4px 14px rgba(0,0,0,.10)', 'кнопка' => 'градиент', 'заголовок' => 'капс', 'список' => 'ромб', 'строка' => '1.6', 'картинка' => 'широкая', 'высота' => 360, 'сдвигТона' => -30, 'интеграция' => 'style'],
