    $т['подложка2'] = "rgba($r,$g,$b," . $т['а2'] . ')';
    $т['линия']     = "rgba($r,$g,$b,.20)";
    if ($т['кант'] === 'none') {
        // без канта заливка карточек гуще, иначе они сливаются с фоном
        $т['подложка']  = "rgba($r,$g,$b," . ($т['а1'] + .06) . ')';
        $т['подложка2'] = "rgba($r,$g,$b," . ($т['а2'] + .06) . ')';
        $т['кантCSS'] = '1px solid transparent';
    } else {
